bun -e '
import { readFileSync } from "node:fs";
import { parseDispatchEmail } from "./src/providers/email.ts";

const oldRe = /(?:tracking(?:\s+id|\s+number)?|gu[ií]a|c[oó]digo de seguimiento|rastreo)\s*[:#]?\s*([A-Z0-9-]{8,40})/i;
const newRe = /(?:tracking(?:\s+id|\s+number)?|gu[ií]a|c[oó]digo de seguimiento|rastreo)\s*[:#]?\s*([A-Z0-9-]{8,40})(?:\s*\(\s*([A-Za-z][A-Za-z0-9 .'"'"'-]{1,40})\s*\))?/i;

function bodyOf(raw) {
  const split = raw.split(/\r?\n\r?\n/);
  return split.length > 1 ? split.slice(1).join("\n") : raw;
}
function oldParse(raw) {
  const text = bodyOf(raw);
  const STORES = [
    { store: "amazon", test: /amazon/i, order: /\b(\d{3}-\d{7}-\d{7})\b/ },
    { store: "mercadolibre", test: /mercado\s?libre/i, order: /(?:venta|pedido|orden|#)\D{0,8}(\d{10,16})/i },
    { store: "ebay", test: /ebay/i, order: /(?:order|pedido)\D{0,8}(\d{2}-\d{5}-\d{5}|\d{10,14})/i },
    { store: "alibaba", test: /alibaba/i, order: /(?:order|pedido)\D{0,12}(\d{12,20})/i },
    { store: "homecenter", test: /homecenter/i, order: /(?:pedido|orden)\D{0,8}(\d{6,12})/i },
  ];
  const store = STORES.find((item) => item.test.test(raw));
  if (!store) return { error: "El correo no pertenece a una tienda cubierta." };
  const order = raw.match(store.order);
  if (!order?.[1]) return { error: `No se encontró el número de pedido de ${store.store}.` };
  const tracking = text.match(oldRe);
  if (!tracking?.[1]) return { error: "El correo no trae una guía." };
  const carrier = text.match(/(?:carrier|transportadora|enviado con|shipped with)\s*[:#]?\s*([A-Za-z][A-Za-z0-9 .'"'"'-]{1,40})/i);
  return { store: store.store, storeOrderNumber: order[1], trackingNumber: tracking[1].trim(), carrier: carrier?.[1]?.trim() };
}

const files = [
  "harness/casos/caso5-homecenter-guia.txt",
  "harness/regresion/reenviado-mercadolibre.txt",
  "fixtures/correos/amazon.txt",
  "fixtures/correos/mercadolibre.txt",
  "fixtures/correos/ebay.txt",
  "fixtures/correos/alibaba.txt",
  "fixtures/correos/homecenter.txt",
];
for (const f of files) {
  const raw = readFileSync(f, "utf8");
  const neu = parseDispatchEmail(raw);
  const old = oldParse(raw);
  const esperado = f.endsWith(".txt") ? f.replace(/\.txt$/, ".json") : "";
  let exp = null;
  try { exp = JSON.parse(readFileSync(esperado, "utf8")); } catch {}
  const sameGuide = JSON.stringify({s: old.store, o: old.storeOrderNumber, t: old.trackingNumber, e: old.error}) === JSON.stringify({s: neu.store, o: neu.storeOrderNumber, t: neu.trackingNumber, e: neu.error});
  console.log("FILE", f);
  console.log("  new", JSON.stringify(neu));
  console.log("  old", JSON.stringify(old));
  if (exp) console.log("  exp", JSON.stringify(exp), "match", JSON.stringify(neu) === JSON.stringify(exp));
  console.log("  same store/order/tracking", sameGuide, "carrier old", old.carrier, "new", neu.carrier);
}

const probes = [
  `From: pedidos@homecenter.com.co\nSubject: x\n\nPedido 771234 de Homecenter va en camino.\nGuía: 7012345678 (Coordinadora)\n`,
  `From: pedidos@homecenter.com.co\nSubject: x\n\nPedido 771234\nGuía: 7012345678 (Amazon 112-4455667-1234567)\n`,
  `From: pedidos@homecenter.com.co\nSubject: x\n\nPedido 111111 de Homecenter.\nGuía: 7012345678 (Coordinadora)\nPedido 222222 de otra compra.\n`,
  `From: envios@mercadolibre.com\nSubject: x\n\nVenta 2000003847563\nCódigo de seguimiento: 999001234567 (nota interna del pedido)\nTransportadora: Servientrega\n`,
  `From: shipment-tracking@amazon.com\n\nOrder #112-4455667-1234567\nTracking ID: 1Z999AA10123456784 (see tracking details)\n`,
  `From: pedidos@homecenter.com.co\n\nPedido 771234\nGuía: pending (Coordinadora)\n`,
  `From: pedidos@homecenter.com.co\n\nPedido 771234\nTracking: pending\nGuía: 7012345678 (Coordinadora)\n`,
  `From: compras@grabit.example\nSubject: Fwd\n\n---------- Forwarded message ---------\nFrom: pedidos@homecenter.com.co\n\nPedido 771234\nGuía: 7012345678 (Coordinadora)\n`,
];
console.log("--- PROBES ---");
for (const raw of probes) {
  const neu = parseDispatchEmail(raw);
  const old = oldParse(raw);
  console.log("NEW", JSON.stringify(neu));
  console.log("OLD", JSON.stringify(old));
  console.log("---");
}
'

